def bul(*lines):return '<ul class="bul">'+''.join(f'<li>{s}</li>' for s in lines)+'</ul>'
def sub(t):return '<div class="sub">'+t+'</div>'
def card(t,txt,ic='chart',h=230):return f'<div class="box fill" style="height:{h}px"><div class="cap" style="height:110px;flex-direction:column;gap:10px"><div class="ic">{icon(ic)}</div>{t}</div><div style="padding:20px 22px">{txt}</div></div>'
def circle(t,x,y,s=85,c=A):return f'<div class="circle" style="position:absolute;left:{x}px;top:{y}px;width:{s}px;height:{s}px;background:{c};color:white;font-size:18px;font-weight:600;line-height:1.5">{t}</div>'
def chart(vals,labels,bar=False,line=True,w=440,h=240):
 pts=[((70 if bar else 35)+i*(w-(140 if bar else 70))/max(1,len(vals)-1),h-35-v/100*((h-20) if h<120 else (h-65))) for i,v in enumerate(vals)]
 s=f'<svg viewBox="0 0 {w} {h}">'
 for y in range(30,h-30,45):s+=f'<path d="M20 {y}H{w-15}" stroke="#ddd" stroke-width="1"/>'
 if bar:
  for i,(x,y) in enumerate(pts):s+=f'<rect x="{x-24}" y="{y-40}" width="48" height="{h-35-y+40}" fill="#d0d0d0" rx="3"/>'
 if line:
  s+='<path d="M'+' L'.join(f'{x},{y}' for x,y in pts)+f' L{pts[-1][0]},{h-35} L{pts[0][0]},{h-35}Z" fill="#e6f4ff"/>'
  s+='<polyline points="'+' '.join(f'{x},{y}' for x,y in pts)+'" fill="none" stroke="#2088f8" stroke-width="1.3"/>'
  for x,y in pts:s+=f'<circle cx="{x}" cy="{y}" r="4" fill="#2088f8"/>'
 for (x,y),lab in zip(pts,labels):s+=f'<text x="{x}" y="{h-12}" text-anchor="middle" font-size="12" fill="#222">{lab}</text>'
 return s+'</svg>'
